preset.frame_eqs_eel:
bass_thresh = above(bass_att,bass_thresh)*2 + (1-above(bass_att,bass_thresh))*((bass_thresh-1.4)*0.85+1.4);
treb_thresh = above(treb_att,treb_thresh)*2 + (1-above(treb_att,treb_thresh))*((treb_thresh-1.5)*0.75+1.5);
bass_on = above(bass_thresh,1.8);
treb_on = above(treb_thresh,1.9);
swapcolour = bass_on - treb_on;
red_aim = if(equal(swapcolour,1),1,if(equal(swapcolour,0),1,0));
green_aim = if(equal(swapcolour,1),0,if(equal(swapcolour,0),0.5,0.25));
blue_aim = if(equal(swapcolour,1),0,if(equal(swapcolour,0),0,1));
red = red + (red_aim - red)*if(equal(swapcolour,1),0.65,0.45);
green = green + (green_aim - green)*0.5;
blue = blue + (blue_aim - blue)*if(equal(swapcolour,1),0.45,0.65);
wave_r = red + 0.2*GREEN;
wave_g = 0.15*green;
wave_b = green+BLUE;
slowtime = slowtime + bnot(time*100%41)+.001;
rot = .1*sin(slowtime);
ying = if(below(ying,1),1,ying);
any_on =bnot((bass_on+mid_on+treb_on)%3);
ying = if (any_on,ying + bnot(time*10%3),ying);
yin = ying%2;
ob_r = (-1 * cos(ying))  + abs(-1 * cos(ying)) ;
ob_b = cos(ying)  + abs(cos(ying));
ob_g = abs(sin(ying)) ;
mv_r = 0.7 - 0.2*sin(time*0.683);
mv_b = 0.9 + 0.1*sin(time*0.832);
mv_g = 0.2 + 0.17*sin(time*1.03);
mv_r =0.7+0.148*(ib_r+ib_b);
mv_b =1-0.2*(ib_r+ib_b);
mv_g =0.6+ 0.19*(ib_g+ib_r);
q1 = 0.32+(bass + bass_att*2)/20;

dx = if(yin,sin(slowtime),if(equal(yin,yang),0,dx));
dy = if(yin,.01*cos(slowtime),0);
yang = bnot(yin);
monitor = any_on;

preset.pixel_eqs_eel:
dx =if(above(x,q1),sin(q1*1.1-x)/5, log10(1/x)/15);
